import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {makePart} from './geometry.js';
import {BALL,createBallWorld,meshTriangles} from './ball-physics.js';
import {ballRamp,RAMP_DROP} from './ball-test-model.js';
import {icon} from './icons.js';
export function ballTestDialog(model,showDialog,selectedIds=[]){
 showDialog(`<div class="ball-heading"><h2>Ball test</h2><span>Fixed build · live balls</span></div><div class="ball-toolbar"><div class="mode-switch"><button id="ball-current" aria-pressed="true">My build</button><button id="ball-selection" aria-pressed="false" ${selectedIds.length?'':'hidden'}>Selection</button><button id="ball-ramp" aria-pressed="false">Try ramp</button></div><button id="ball-drop" aria-pressed="false">${icon('add')} Drop ball</button><button id="ball-feed" title="Drop a ball at the start of the ramp" hidden>${icon('add')} Feed ramp</button><button id="ball-play" aria-pressed="true">Ⅱ Pause</button><button id="ball-clear">${icon('rotate')} Clear</button><button id="ball-fit" title="Fit model">${icon('frame')}</button></div><div class="ball-stage"><div id="ball-canvas"></div><span class="ball-count">0 / 16 balls</span><span id="ball-hint">Drag to orbit · Scroll to zoom</span><div id="ball-message" role="status"></div></div><details class="ball-info"><summary>Ball &amp; physics settings</summary><div class="ball-settings"><span class="ball-swatch"></span><div><strong>90990 + 90991</strong><br>Red/yellow ball · ≈46 mm</div><label>Mass estimate <input id="ball-mass" type="number" min="1" max="100" step="1" value="24"> g</label><label>Grip <input id="ball-grip" type="range" min="0" max="1" step="0.02" value="0.24"></label><label>Bounce <input id="ball-bounce" type="range" min="0" max="0.8" step="0.02" value="0.18"></label></div><p>Gravity, rolling and ball collisions against the visible part surfaces. All build parts stay fixed, including unlocked parts. No moving lifts, motor contact or flexible-track deformation yet. Settings restart the ball test. Material properties and hollow-shell inertia are estimates. Up to 16 balls and 300,000 collision triangles; speed is capped at 5 m/s. Slow devices run the test more slowly.</p><p><a href="https://www.knexusergroup.org.uk/en/knex-hint-R5.html" target="_blank" rel="noreferrer">Original ball-coaster parts</a> · The ramp uses orange tubing, orange track clips and blue cross-rods, held fixed as a test fixture. Close to return to your unchanged build.</p></details>`);
 const dialog=document.querySelector('#dialog'),$=s=>dialog.querySelector(s);dialog.classList.add('ball-dialog');
 const scene=new T.Scene();scene.background=new T.Color('#202934');const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;$('#ball-canvas').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','Ball-test 3D view. Enable Drop ball and click a surface.');
 const camera=new T.PerspectiveCamera(40,1,1,20000),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=60;controls.maxDistance=7000;
 scene.add(new T.HemisphereLight('#ffffff','#788ca3',2.5));const sun=new T.DirectionalLight('#fff4dc',3);sun.position.set(-200,500,300);scene.add(sun);
 const floor=new T.Mesh(new T.PlaneGeometry(20000,20000),new T.MeshStandardMaterial({color:'#3c4858',roughness:.95}));floor.rotation.x=-Math.PI/2;floor.position.y=-.1;scene.add(floor);const grid=new T.GridHelper(4000,160,'#5a6a7e','#49566a');grid.position.y=.1;scene.add(grid);
 let root=new T.Group(),sim=null,balls=[],running=true,dropMode=false,ramp=false,selectionMode=false,alive=true,raf,last=0,pointerDown=null,spawn=null;
 const sphere=new T.SphereGeometry(BALL.radius,32,24),upper=new T.SphereGeometry(BALL.radius,32,12,0,Math.PI*2,0,Math.PI/2),lower=new T.SphereGeometry(BALL.radius,32,12,0,Math.PI*2,Math.PI/2,Math.PI/2),red=new T.MeshStandardMaterial({color:'#e33b45',roughness:.35}),yellow=new T.MeshStandardMaterial({color:'#ffd22f',roughness:.35});
 const preview=new T.Mesh(sphere,new T.MeshBasicMaterial({color:'#72f5c2',transparent:true,opacity:.38,wireframe:true}));preview.visible=false;scene.add(preview);
 const ray=new T.Raycaster(),mouse=new T.Vector2(),surface=new T.Plane(new T.Vector3(0,1,0),0);
 const say=text=>$('#ball-message').textContent=text;
 function fit(){const box=new T.Box3().setFromObject(root),center=box.isEmpty()?new T.Vector3(0,80,0):box.getCenter(new T.Vector3()),size=box.isEmpty()?450:Math.max(box.getSize(new T.Vector3()).length(),200);controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(.55,.65,1).normalize().multiplyScalar(size*1.45));controls.update();}
 function clear(){sim?.clear();for(const b of balls)scene.remove(b.mesh);balls=[];$('.ball-count').textContent='0 / 16 balls';}
 function releaseParts(){root.traverse(o=>{if(o.userData.ownedBallTest)o.traverse(m=>{m.geometry?.dispose();if(m.material)(Array.isArray(m.material)?m.material:[m.material]).forEach(x=>x.dispose());});});scene.remove(root);}
 function load(useRamp,useSelection=false){clear();releaseParts();ramp=useRamp;selectionMode=useSelection;root=new T.Group();scene.add(root);const source=useRamp?ballRamp():useSelection?{parts:model.parts.filter(p=>selectedIds.includes(p.id))}:model;
  for(const p of source.parts){const o=makePart(p.type,p);o.position.fromArray(p.pos);o.quaternion.fromArray(p.quat);if(p.path||p.belt)o.userData.ownedBallTest=true;root.add(o);}
  sim=null;try{sim=createBallWorld(meshTriangles(root),{mass:Number($('#ball-mass').value),friction:Number($('#ball-grip').value),bounce:Number($('#ball-bounce').value)});say(useRamp?'Feed ramp to start rolling.':selectionMode?'Only the selected parts are included. Drop a ball to test.':'Choose Drop ball, then click above your build.');}catch(e){say(e.message);}
  $('#ball-current').setAttribute('aria-pressed',String(!ramp&&!selectionMode));$('#ball-selection').setAttribute('aria-pressed',String(selectionMode));$('#ball-ramp').setAttribute('aria-pressed',String(ramp));$('#ball-feed').hidden=!ramp;$('#ball-drop').disabled=!sim;$('#ball-feed').disabled=!sim;spawn=null;preview.visible=false;fit();
 }
 function add(position){if(!sim)return;try{const body=sim.drop(position),mesh=new T.Group();mesh.add(new T.Mesh(upper,red),new T.Mesh(lower,yellow));scene.add(mesh);balls.push({body,mesh});mesh.position.fromArray(position);$('.ball-count').textContent=`${balls.length} / 16 balls`;say(running?'': 'Paused. Press Play to release.');}catch(e){say(e.message);}}
 function aim(e){if(!dropMode||!sim)return;const rect=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(mouse,camera);const hits=ray.intersectObject(root,true);let point;
  if(hits.length){const hit=hits[0],normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);if(normal.dot(ray.ray.direction)>0)normal.negate();point=hit.point.clone().addScaledVector(normal,BALL.radius+3);}else{point=ray.ray.intersectPlane(surface,new T.Vector3());if(point)point.y=BALL.radius+80;}
  spawn=point?.toArray()??null;preview.visible=!!point;if(point){preview.position.copy(point);preview.material.color.set(sim.canDrop(spawn)?'#72f5c2':'#ff5884');}
 }
 renderer.domElement.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY,button:e.button};});renderer.domElement.addEventListener('pointermove',aim);renderer.domElement.addEventListener('pointerleave',()=>{preview.visible=false;spawn=null;});renderer.domElement.addEventListener('pointerup',e=>{if(pointerDown?.button===0&&Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)<5&&dropMode){aim(e);if(spawn)add(spawn);}pointerDown=null;});
 $('#ball-drop').onclick=()=>{dropMode=!dropMode;controls.enableRotate=!dropMode;$('#ball-drop').setAttribute('aria-pressed',String(dropMode));$('#ball-hint').textContent=dropMode?'Click to drop · Right-drag to pan · Scroll to zoom':'Drag to orbit · Scroll to zoom';renderer.domElement.style.cursor=dropMode?'crosshair':'grab';preview.visible=false;};
 $('#ball-play').onclick=()=>{running=!running;$('#ball-play').textContent=running?'Ⅱ Pause':'▶ Play';$('#ball-play').setAttribute('aria-pressed',String(running));say(running?'':'Paused. Press Play to release.');};$('#ball-clear').onclick=()=>{clear();say('Balls cleared.');};$('#ball-fit').onclick=fit;
 $('#ball-current').onclick=()=>load(false);$('#ball-selection').onclick=()=>load(false,true);$('#ball-ramp').onclick=()=>load(true);$('#ball-feed').onclick=()=>add(RAMP_DROP);for(const id of ['#ball-mass','#ball-grip','#ball-bounce'])$(id).onchange=()=>load(ramp,selectionMode);
 const resize=new ResizeObserver(()=>{const w=$('#ball-canvas').clientWidth,h=$('#ball-canvas').clientHeight;if(w&&h){renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}});resize.observe($('#ball-canvas'));
 function tick(time){if(!alive)return;const dt=last?(time-last)/1000:0;last=time;if(running)sim?.step(dt);for(const {body,mesh} of balls){mesh.position.set(body.position.x*1000,body.position.y*1000,body.position.z*1000);mesh.quaternion.copy(body.quaternion);}controls.update();renderer.render(scene,camera);raf=requestAnimationFrame(tick);}
 function dispose(){alive=false;cancelAnimationFrame(raf);resize.disconnect();clear();releaseParts();controls.dispose();renderer.dispose();[sphere,upper,lower,floor.geometry,grid.geometry].forEach(g=>g.dispose());[red,yellow,preview.material,floor.material,...(Array.isArray(grid.material)?grid.material:[grid.material])].forEach(m=>m.dispose());dialog.classList.remove('ball-dialog');dialog.removeEventListener('close',dispose);}
 dialog.addEventListener('close',dispose);load(false,selectedIds.length>0);raf=requestAnimationFrame(tick);
}
